// Generated by AI (UnitTest MCP)
use super::*;

const MIN_GROUNDING_TERMS: usize = 3;

impl GraphStore {
    /// Whether semantic hits contain a majority of the query's information.
    /// IDF makes repository-specific terms outweigh generic shared vocabulary.
    pub(crate) fn recall_is_grounded(&self, query: &str, nodes: &[Node]) -> Result<bool> {
        if nodes.is_empty() {
            return Ok(false);
        }
        let terms = informative_terms(query);
        if terms.len() < MIN_GROUNDING_TERMS {
            return Ok(true);
        }

        let evidence = nodes
            .iter()
            .flat_map(|node| [&node.label, node.content.as_deref().unwrap_or("")])
            .flat_map(words)
            .collect::<HashSet<_>>();
        let node_count: f64 = self
            .conn
            .query_row("SELECT COUNT(*) FROM nodes", [], |row| row.get::<_, i64>(0))?
            as f64;
        let mut total_weight = 0.0;
        let mut supported_weight = 0.0;
        for term in terms {
            let documents: f64 = self.conn.query_row(
                "SELECT COUNT(*) FROM nodes_fts WHERE nodes_fts MATCH ?1",
                params![format!("\"{term}\"")],
                |row| row.get::<_, i64>(0),
            )? as f64;
            let weight = ((node_count + 1.0) / (documents + 1.0)).ln() + 1.0;
            total_weight += weight;
            if evidence.contains(&term) {
                supported_weight += weight;
            }
        }
        Ok(supported_weight * 2.0 >= total_weight)
    }
}

fn informative_terms(input: &str) -> HashSet<String> {
    words(input)
        .filter(|term| term.len() >= 3 && !is_stopword(term))
        .collect()
}

fn words(input: &str) -> impl Iterator<Item = String> + '_ {
    input
        .split(|character: char| !character.is_alphanumeric())
        .filter(|term| !term.is_empty())
        .map(str::to_lowercase)
}

fn is_stopword(term: &str) -> bool {
    matches!(
        term,
        "and"
            | "are"
            | "been"
            | "being"
            | "but"
            | "can"
            | "could"
            | "did"
            | "does"
            | "for"
            | "from"
            | "how"
            | "into"
            | "never"
            | "only"
            | "should"
            | "that"
            | "the"
            | "then"
            | "these"
            | "this"
            | "those"
            | "was"
            | "were"
            | "what"
            | "when"
            | "where"
            | "which"
            | "who"
            | "why"
            | "will"
            | "with"
            | "without"
            | "would"
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::graph::test_support::{store, NOW};

    fn add(store: &GraphStore, id: &str, text: &str) -> Node {
        let node = Node::new(id, NodeType::Intent, text, NOW).with_content(text);
        store.upsert_node(&node).unwrap();
        node
    }

    /// Bug: semantic outliers made recall answer gibberish and absent-domain
    /// questions with plausible strangers. That distracts the caller; the fix
    /// requires the returned evidence to ground the query before serving it.
    #[test]
    fn unrelated_semantic_hits_are_not_an_answer() {
        let graph = store();
        let hit = add(
            &graph,
            "intent:release",
            "release build reads the current branch",
        );

        assert!(!graph
            .recall_is_grounded("postgresql autovacuum billion row table", &[hit])
            .unwrap());
    }

    #[test]
    fn a_majority_of_idf_weighted_query_information_is_grounded() {
        let graph = store();
        let hit = add(
            &graph,
            "intent:lease",
            "a lapsed lease stops work from certifying",
        );

        assert!(graph
            .recall_is_grounded("why does a lapsed lease stop the work certifying", &[hit])
            .unwrap());
    }

    #[test]
    fn generic_matches_do_not_outweigh_unsupported_rare_terms() {
        let graph = store();
        for index in 0..12 {
            add(
                &graph,
                &format!("intent:generic-{index}"),
                "report failure command",
            );
        }
        let hit = graph.get_node("intent:generic-0").unwrap().unwrap();

        assert!(!graph
            .recall_is_grounded(
                "why does powershell report failure for a command that succeeded",
                &[hit],
            )
            .unwrap());
    }

    #[test]
    fn short_fuzzy_queries_keep_the_existing_recall_contract() {
        let graph = store();
        let hit = add(&graph, "intent:lease", "claim expiry");

        assert!(graph.recall_is_grounded("lapsed lease", &[hit]).unwrap());
    }
}
